sys_script_include.script:
var DrivePermissionAPI = Class.create();
DrivePermissionAPI.CONSTANTS = {
    API_CONFIG: {
        LIST_PERM: {
            path: "/drive/v3/files/${fileId}/permissions",
            httpMethod: "GET",
            pathParams: ["fileId"],
            queryParams: [
                "pageSize",
                "pageToken",
                "supportsAllDrives",
                "useDomainAdminAccess",
                "includePermissionsForView"
            ]
        }
    }
};
DrivePermissionAPI.prototype = Object.extend(new x_neyu_google_nyu.RestUtil(), {
    initialize: function() {
        this.oauthProvider = "1b757d762bf08f10da0ef1bece91bfb2";
        this.providerProfile = "58c5bdb62bf08f10da0ef1bece91bf94";
        this.jwtProviderSysId = "4ea4b1762bf08f10da0ef1bece91bff7";
        this.credential = gs.getProperty("x_neyu_google_nyu.directory.api.credential.id");
        this.serviceAccount = gs.getProperty("x_neyu_google_nyu.drive.api.service.account");
        this.aliasId = "ec8ea13e2bb08f10da0ef1bece91bfa9";
        this.scopes = "https://www.googleapis.com/auth/drive.metadata.readonly";
    },

    listPermissions: function(fileId, {
        userEmail = null,
        pageSize = 100,
        pageToken = null,
        supportsAllDrives = false,
        useDomainAdminAccess = false,
        includePermissionsForView = null
    } = {}) {
        gs.info(`[listPermissions] fileId: ${fileId}` +
            `\nuserEmail: ${userEmail}` +
            `\npageSize: ${pageSize}` +
            `\npageToken: ${pageToken}` +
            `\nsupportsAllDrives: ${supportsAllDrives}` +
            `\nincludePermissionsForView: ${includePermissionsForView}`);

        const pathParams = {
            fileId: fileId
        };

        const queryParams = {};

        if (!gs.nil(pageSize)) {
            queryParams["pageSize"] = pageSize;
        }
        if (!gs.nil(pageToken)) {
            queryParams["pageToken"] = pageToken;
        }
        if (!gs.nil(supportsAllDrives)) {
            queryParams["supportsAllDrives"] = supportsAllDrives;
        }
        if (!gs.nil(includePermissionsForView)) {
            queryParams["includePermissionsForView"] = includePermissionsForView;
        }

        const config = DrivePermissionAPI.CONSTANTS.API_CONFIG.LIST_PERM;
        const requestConfig = {
            ...config,
            skipSystemAuth: !gs.nil(userEmail) ? true : false,
            aliasId: this.aliasId,
            pathParams,
            queryParams
        };

        if (requestConfig["skipSystemAuth"]) {
            const access_token = this.generateUserToken(userEmail, this.jwtProviderSysId, this.serviceAccount, this.scopes);
            const headers = {
                "Authorization": `Bearer ${access_token}`
            };
            requestConfig["headers"] = headers;
        } else {
            this.ensureToken(this.credential, this.oauthProvider, this.providerProfile);
        }

        const response = this.execute(requestConfig, "listPermissions");

        if (response.error) {
            gs.error(`[listPermissions] There was an error.\nRequest: ${JSON.stringify(response)}`);
        }

        return {
            ...response
        };
    },

    type: 'DrivePermissionAPI'
});
